import unittest
from candidate import flip_case

class TestFlipCase(unittest.TestCase):
    def test_flip_case_normal_mixed_case(self):
        self.assertEqual(flip_case('Hello'), 'hELLO')

    def test_flip_case_empty_string(self):
        self.assertEqual(flip_case(''), '')

    def test_flip_case_none_input_raises_error(self):
        with self.assertRaises((AttributeError, TypeError)):
            flip_case(None)

    def test_flip_case_integer_raises_error(self):
        with self.assertRaises((AttributeError, TypeError)):
            flip_case(123)

    def test_flip_case_all_uppercase(self):
        self.assertEqual(flip_case('HELLO'), 'hello')

    def test_flip_case_all_lowercase(self):
        self.assertEqual(flip_case('hello'), 'HELLO')

    def test_flip_case_string_with_special_characters_and_numbers(self):
        self.assertEqual(flip_case('Hello123!@#'), 'hELLO123!@#')
